/// Split valid Unicode scalar text into nonempty lines.
///
/// Recognizes the separators used by Python's `str.splitlines()` and removes
/// empty lines without trimming any other content.
pub fn split_nonempty(input: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut chars = input.char_indices().peekable();

    while let Some((index, ch)) = chars.next() {
        if is_line_boundary(ch) {
            if start < index {
                lines.push(input[start..index].to_owned());
            }
            start = index + ch.len_utf8();

            // Python treats CRLF as one boundary.
            if ch == '\r' {
                if let Some(&(next_index, '\n')) = chars.peek() {
                    chars.next();
                    start = next_index + 1;
                }
            }
        }
    }

    if start < input.len() {
        lines.push(input[start..].to_owned());
    }
    lines
}

fn is_line_boundary(ch: char) -> bool {
    matches!(
        ch,
        '\n' | '\r'
            | '\x0b'
            | '\x0c'
            | '\x1c'
            | '\x1d'
            | '\x1e'
            | '\u{85}'
            | '\u{2028}'
            | '\u{2029}'
    )
}

#[cfg(test)]
mod tests {
    use super::split_nonempty;

    #[test]
    fn python_separators() {
        for separator in [
            "\n", "\r", "\r\n", "\x0b", "\x0c", "\x1c", "\x1d", "\x1e", "\u{85}", "\u{2028}",
            "\u{2029}",
        ] {
            assert_eq!(
                split_nonempty(&format!("a{separator}b{separator}")),
                ["a", "b"]
            );
        }
    }

    #[test]
    fn whitespace_is_not_trimmed() {
        assert_eq!(split_nonempty(" a \n \nb "), [" a ", " ", "b "]);
    }

    #[test]
    fn empty_lines_are_removed() {
        assert!(split_nonempty("\n\r\n").is_empty());
        assert!(split_nonempty("").is_empty());
    }

    #[test]
    fn other_control_characters_are_content() {
        assert_eq!(split_nonempty("a\x1fb"), ["a\x1fb"]);
    }
}

